from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    flat = [v for row in grid for v in row]
    background = Counter(flat).most_common(1)[0][0]
    for row in out:
        positions = [j for j, v in enumerate(row) if v != background]
        if positions:
            last = max(positions)
            for j in range(last + 1, len(row)):
                if row[j] == background:
